// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * The initial run import's marker must be on disk before the import's first native commit, so a crash that keeps any of
 * the import's data also keeps the marker. Syncing it must not hold up the adds, and the marker's deletion is synced
 * only when the store syncs its commits.
 */
class LmdbInitialRunImportMarkerSyncTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("http://example.com/marker-sync/p");

	@TempDir
	File directory;

	private final ExecutorService writerThread = Executors.newSingleThreadExecutor();
	private final List<String> syncs = new CopyOnWriteArrayList<>();
	private Consumer<Path> previousHook;
	private Path dataDir;
	private Path marker;

	@BeforeEach
	void recordSyncs() {
		dataDir = directory.toPath().toAbsolutePath();
		marker = dataDir.resolve(LmdbInitialRunImport.MARKER_FILE_NAME);
		previousHook = LmdbInitialRunImport.beforeSyncForTest;
		LmdbInitialRunImport.beforeSyncForTest = this::record;
	}

	@AfterEach
	void restore() {
		LmdbInitialRunImport.beforeSyncForTest = previousHook;
		writerThread.shutdownNow();
	}

	private void record(Path path) {
		Path absolute = path.toAbsolutePath();
		if (absolute.equals(marker)) {
			syncs.add("marker");
		} else if (absolute.equals(dataDir)) {
			syncs.add(Files.exists(marker) ? "directory with marker" : "directory without marker");
		}
	}

	@Test
	@Timeout(60)
	void aStoreThatDoesNotSyncItsCommitsDoesNotSyncTheMarkerDeletion() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config(false));
		sail.init();
		try {
			importSubjects(sail, 2_000);
			assertThat(sail.getBackingStore().initialRunImportsCompleted()).isEqualTo(1);
			assertThat(syncs).containsExactly("marker", "directory with marker");
		} finally {
			sail.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void aStoreThatSyncsItsCommitsSyncsTheMarkerDeletion() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config(true));
		sail.init();
		try {
			importSubjects(sail, 2_000);
			assertThat(sail.getBackingStore().initialRunImportsCompleted()).isEqualTo(1);
			assertThat(syncs).containsExactly("marker", "directory with marker", "directory without marker");
		} finally {
			sail.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void addsContinueWhileTheMarkerSyncsAndTheCommitWaitsForIt() throws Exception {
		CountDownLatch syncStarted = new CountDownLatch(1);
		CountDownLatch releaseSync = new CountDownLatch(1);
		LmdbInitialRunImport.beforeSyncForTest = path -> {
			if (path.toAbsolutePath().equals(marker)) {
				syncStarted.countDown();
				try {
					releaseSync.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
				}
			}
			record(path);
		};
		LmdbStore sail = new LmdbStore(directory, config(false));
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			LmdbStoreConnection writer = writerThread.submit(() -> (LmdbStoreConnection) sail.getConnection()).get();
			try {
				Future<?> adds = writerThread.submit(() -> {
					writer.begin(IsolationLevels.NONE);
					addSubjects(writer, 0, 2_000);
				});
				assertThat(syncStarted.await(30, TimeUnit.SECONDS)).as("the import started its marker sync").isTrue();
				adds.get(10, TimeUnit.SECONDS);
				assertThat(backing.isInitialRunImportActive()).isTrue();

				// The waiting commit holds the store lock: observe it only through lock-free commit counters.
				long tripleCommits = backing.getTripleStore().getNativeCommitGeneration();
				long valueCommits = backing.valueStore().nativeCommitGeneration();
				Future<?> commit = writerThread.submit(writer::commit);
				Thread.sleep(300);
				assertThat(commit).as("the commit waits for the marker").isNotDone();
				assertThat(backing.getTripleStore().getNativeCommitGeneration())
						.as("nothing of the import committed before its marker is on disk")
						.isEqualTo(tripleCommits);
				assertThat(backing.valueStore().nativeCommitGeneration()).isEqualTo(valueCommits);

				releaseSync.countDown();
				commit.get(30, TimeUnit.SECONDS);
			} finally {
				releaseSync.countDown();
				writerThread.submit(writer::close).get(30, TimeUnit.SECONDS);
			}
			assertThat(backing.initialRunImportsCompleted()).isEqualTo(1);
			assertThat(marker).doesNotExist();
			assertImported(sail, 2_000);
		} finally {
			sail.shutDown();
		}
	}

	private void importSubjects(LmdbStore sail, int subjects) {
		try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
			writer.begin(IsolationLevels.NONE);
			addSubjects(writer, 0, subjects);
			writer.commit();
		}
		assertImported(sail, subjects);
	}

	private static void addSubjects(LmdbStoreConnection writer, int from, int to) {
		for (int i = from; i < to; i++) {
			writer.addStatement(subject(i), P, VF.createLiteral("value " + i));
		}
	}

	private static IRI subject(int i) {
		return VF.createIRI("http://example.com/marker-sync/subject/" + i);
	}

	private static void assertImported(LmdbStore sail, int subjects) {
		try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
			assertThat(reader.size()).isEqualTo(subjects);
			try (var statements = reader.getStatements(null, null, VF.createLiteral("value " + (subjects - 1)),
					false)) {
				assertThat(statements.stream().count()).as("value lookup records exist").isEqualTo(1);
			}
		}
	}

	private static LmdbStoreConfig config(boolean forceSync) {
		return new LmdbStoreConfig("spoc,posc").setForceSync(forceSync)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setBulkOperationSize(64);
	}
}
